use core::io::BorrowedBuf;
use std::mem::MaybeUninit;

fn main() {
    let mut bytes = [0; 32];
    let mut buf = BorrowedBuf::from(&mut bytes[..]);
    buf.unfilled().as_mut()[1] = MaybeUninit::uninit();
    dbg!(bytes);
}
