This creates a tower of coroutines. It's both clearer and more efficient to define the `every` predicate for your data structure, use that for the recursion, then finally write the public iterator as a trivial wrapper around it that discards the final boolean result:


```
func (s *Schema) all() iter.Seq[*Schema] {
	return func(yield func(*Schema) bool) {
		_ = s.every(yield)
	}
}

// every reports whether f is true for every Schema in the tree rooted at s.
// f is called in preorder.
func (s *Schema) every(f func(*Schema) bool) bool {
	if !f(s) {
		return false
