from dataclasses import dataclass

@dataclass(order=True)
class A:
    int

class B(A):
    def __lt__(self, other: A) -> bool:
        return True

    def __le__(self, other: A) -> bool:
        return True

    __gt__ = __lt__
    __ge__ = __le__
